<?php
// Phase 10 · Q1b — generate the four DB/filesystem-derived reference docs a template ships under
// templates/<tpl>/docs/: site-map.md, inventory.md, blocks.md, positions.md. The six hand-written
// docs next to them (design-system, recipes, checks, content-rules, cowork-api, languages) are
// NOT touched. Each generated file opens with a banner naming this script: an agent that edits a
// generated file by hand is editing something the next run overwrites.
//
// Runs INSIDE the Joomla PHP runtime (the web container, or `ddev exec php`), from the site root,
// after the LAST content change and before the Akeeba capture — the backup takes the site as-is,
// so a run before the final edit ships a stale inventory. Drive it with gen-docs.sh; direct use:
//
//   php gen-docs.php --template=<tpl> [--base=http://…] [--block-prefix=<p>] [--layout-prefix=<p>]
//                    [--base-template=<name>] [--purposes=<json>] [--root=/var/www/html]
//
//   --template       template folder name under templates/ (required)
//   --base           the build copy's URL, printed in site-map.md for orientation (default: live_site)
//   --block-prefix   ACM block dirs that belong to THIS template (e.g. `tb-`); other dirs are
//                    listed as inherited leftovers unless a module uses them (default: all dirs)
//   --layout-prefix  etc/layout/*.json that belong to this template (default: all)
//   --base-template  the quickstart base this template was built on, named in the leftover notes
//   --purposes       JSON map position → one-line purpose, merged into positions.md
//                    (default: <template>/docs/positions.purposes.json when it exists)
//   --root           Joomla root (default: /var/www/html, or JPATH_BASE when already defined)
//
// Reference: references/agent-docs.md — what each shipped document is for and who writes it.

$KNOWN = ['template', 'base', 'block-prefix', 'layout-prefix', 'base-template', 'purposes', 'root', 'help'];
$opt = [];
foreach (array_slice($argv ?? [], 1) as $a) {
    if (preg_match('/^--([a-z-]+)(?:=(.*))?$/', $a, $m) && in_array($m[1], $KNOWN, true)) { $opt[$m[1]] = $m[2] ?? '1'; }
    else { fwrite(STDERR, "gen-docs: unknown argument $a\n"); exit(2); }
}
if (!empty($opt['help'])) { fwrite(STDOUT, "usage: php gen-docs.php --template=<tpl> [--base=URL] [--block-prefix=P] [--layout-prefix=P] [--base-template=NAME] [--purposes=FILE] [--root=DIR]\n"); exit(0); }
$TPL = $opt['template'] ?? '';
if ($TPL === '' || !preg_match('/^[a-z0-9_]+$/', $TPL)) { fwrite(STDERR, "gen-docs: --template=<folder name> is required (letters, digits, _)\n"); exit(2); }
$BLOCK_PREFIX = $opt['block-prefix'] ?? '';
$LAYOUT_PREFIX = $opt['layout-prefix'] ?? '';
$BASE_TPL = $opt['base-template'] ?? '';

// ---------------------------------------------------------------- boot Joomla (CLI, read-only)
if (!defined('_JEXEC')) { define('_JEXEC', 1); }
if (!defined('JPATH_BASE')) { define('JPATH_BASE', rtrim($opt['root'] ?? '/var/www/html', '/')); }
if (!is_file(JPATH_BASE . '/includes/defines.php')) { fwrite(STDERR, "gen-docs: no Joomla at " . JPATH_BASE . " (use --root)\n"); exit(2); }
require_once JPATH_BASE . '/includes/defines.php';
require_once JPATH_BASE . '/includes/framework.php';
$container = \Joomla\CMS\Factory::getContainer();
$container->alias('session', 'session.cli')
    ->alias('JSession', 'session.cli')
    ->alias(\Joomla\CMS\Session\Session::class, 'session.cli')
    ->alias(\Joomla\Session\Session::class, 'session.cli')
    ->alias(\Joomla\Session\SessionInterface::class, 'session.cli');
$app = $container->get(\Joomla\Console\Application::class);
\Joomla\CMS\Factory::$application = $app;
$app->createExtensionNamespaceMap();
$db = \Joomla\CMS\Factory::getDbo();
$BASE = $opt['base'] ?? (string) ($app->get('live_site') ?: 'http://127.0.0.1');

$T = JPATH_BASE . "/templates/$TPL";
if (!is_dir($T) || !is_file("$T/templateDetails.xml")) { fwrite(STDERR, "gen-docs: $T is not a template (no templateDetails.xml)\n"); exit(2); }
$OUT = "$T/docs";
if (!is_dir($OUT) && !mkdir($OUT, 0755, true)) { fwrite(STDERR, "gen-docs: cannot create $OUT\n"); exit(1); }
$purposesFile = $opt['purposes'] ?? "$OUT/positions.purposes.json";
$purpose = is_file($purposesFile) ? (json_decode(file_get_contents($purposesFile), true) ?: []) : [];

$stamp = gmdate('Y-m-d H:i') . ' UTC';
$banner = static fn (string $what) => "<!-- GENERATED by scripts/quickstart/gen-docs.php on $stamp — $what. Do not edit; regenerate. -->\n\n";
$q = static fn (string $sql) => $db->setQuery($sql)->loadObjectList();
$md = static fn ($v) => str_replace('|', '\\|', trim((string) $v));
$log = static function (string $m): void { fwrite(STDOUT, $m . "\n"); };
$ours = static fn (string $name, string $prefix) => $prefix === '' || str_starts_with($name, $prefix);
$inherited = $BASE_TPL !== '' ? "Inherited from $BASE_TPL" : 'Inherited from the base quickstart';

$langs = [];
foreach ($q("SELECT lang_code, sef, title FROM #__languages WHERE published = 1 ORDER BY ordering") as $l) { $langs[$l->lang_code] = $l; }

// ---------------------------------------------------------------- site-map.md
$assocMenu = [];
foreach ($q("SELECT a.id, a.key, m.language FROM #__associations a JOIN #__menu m ON m.id = a.id WHERE a.context = 'com_menus.item'") as $r) { $assocMenu[$r->key][$r->language] = (int) $r->id; }
$assocByItem = [];
foreach ($assocMenu as $k => $set) { foreach ($set as $lang => $id) { $assocByItem[$id] = $set; } }
$styles = [];
foreach ($q("SELECT id, title, home, params FROM #__template_styles WHERE template = " . $db->quote($TPL)) as $s) { $styles[$s->id] = $s; }
$defaultStyle = null; foreach ($styles as $s) { if ($s->home) { $defaultStyle = $s; } }
if (!$defaultStyle) { fwrite(STDERR, "gen-docs: template $TPL has no default style — is it the site's template?\n"); exit(1); }
$items = $q("SELECT id, menutype, title, alias, path, level, parent_id, link, type, language, home, template_style_id, params, published FROM #__menu WHERE client_id = 0 AND id > 1 AND published = 1 ORDER BY menutype, lft");
$types = $q("SELECT menutype, title, description FROM #__menu_types ORDER BY menutype");
$url = static function ($it) use ($langs) {
    $sef = $langs[$it->language]->sef ?? null;
    if (!$sef) { return '—'; }
    return $it->home ? "/$sef/" : "/$sef/" . $it->path;
};
$view = static function ($it) {
    if ($it->type !== 'component') { return $it->type; }
    parse_str(parse_url($it->link, PHP_URL_QUERY) ?: '', $qs);
    $v = ($qs['option'] ?? '?') . ':' . ($qs['view'] ?? '');
    if (!empty($qs['layout'])) { $v .= ' (' . $qs['layout'] . ')'; }
    if (!empty($qs['id'])) { $v .= ' #' . $qs['id']; }
    return $v;
};
$out = $banner('menu tree, routes, view, style, associations from #__menu / #__menu_types / #__associations / #__template_styles');
$out .= "# Site map — every published menu item, " . (count($langs) > 1 ? 'all languages' : 'one language') . "\n\n";
$out .= "Base URL **on the build copy** `$BASE` (the live site has its own host — paths are what matter). Default style: **{$md($defaultStyle->title)}** (id {$defaultStyle->id}); items with another style are marked. ";
$out .= "`assoc` = the id of the same page in the other language (Joomla association — the language switcher follows it).\n\n";
foreach ($types as $t) {
    $rows = array_values(array_filter($items, static fn ($i) => $i->menutype === $t->menutype));
    if (!$rows) { continue; }
    $out .= "## `{$t->menutype}` — {$md($t->title)} (" . count($rows) . " items)\n\n";
    $out .= "| # | item | URL | view | `page_title` (last crumb, if set) | style | assoc |\n|---|---|---|---|---|---|---|\n";
    foreach ($rows as $it) {
        $p = json_decode($it->params ?: '{}', true) ?: [];
        $indent = str_repeat('· ', max(0, $it->level - 1));
        $style = $it->template_style_id && isset($styles[$it->template_style_id]) ? $styles[$it->template_style_id]->title : '';
        $assoc = '';
        foreach ($assocByItem[$it->id] ?? [] as $lang => $id) { if ($id !== (int) $it->id) { $assoc .= ($langs[$lang]->sef ?? $lang) . ' #' . $id . ' '; } }
        $out .= "| {$it->id} | {$indent}{$md($it->title)}" . ($it->home ? ' **(home)**' : '') . " | `{$url($it)}` | `{$md($view($it))}` | {$md($p['page_title'] ?? '')} | {$md($style)} | {$md($assoc)} |\n";
    }
    $out .= "\n";
}
$cats = $q("SELECT c.id, c.title, c.path, c.level, c.language, c.params, (SELECT COUNT(*) FROM #__content x WHERE x.catid = c.id AND x.state = 1) n FROM #__categories c WHERE c.extension = 'com_content' AND c.published = 1 AND c.id > 1 ORDER BY c.lft");
$out .= "## Content categories (`com_content`) — " . count($cats) . "\n\n| id | category | lang | published articles | category layout |\n|---|---|---|---|---|\n";
foreach ($cats as $c) { $p = json_decode($c->params ?: '{}', true) ?: []; $out .= "| {$c->id} | " . str_repeat('· ', max(0, $c->level - 1)) . "{$md($c->title)} | {$c->language} | {$c->n} | {$md($p['category_layout'] ?? '')} |\n"; }
$arts = $q("SELECT a.id, a.title, a.alias, a.language, a.catid, a.attribs, a.note, c.title cat FROM #__content a JOIN #__categories c ON c.id = a.catid WHERE a.state = 1 ORDER BY c.lft, a.language, a.ordering, a.id");
$out .= "\n## Published articles — " . count($arts) . "\n\n| id | title | lang | category | article layout | note |\n|---|---|---|---|---|---|\n";
foreach ($arts as $a) { $p = json_decode($a->attribs ?: '{}', true) ?: []; $out .= "| {$a->id} | {$md($a->title)} | {$a->language} | {$md($a->cat)} | {$md($p['article_layout'] ?? '')} | {$md($a->note)} |\n"; }
$tags = $q("SELECT id, title, language, (SELECT COUNT(*) FROM #__contentitem_tag_map m WHERE m.tag_id = t.id) n FROM #__tags t WHERE published = 1 AND id > 1 ORDER BY lft");
$out .= "\n## Tags — " . count($tags) . "\n\n| id | tag | lang | items |\n|---|---|---|---|\n";
foreach ($tags as $t) { $out .= "| {$t->id} | {$md($t->title)} | {$t->language} | {$t->n} |\n"; }
$contacts = $q("SELECT id, name, language, published FROM #__contact_details ORDER BY id");
$out .= "\n## Contacts (`com_contact`) — " . count($contacts) . "\n\n| id | name | lang |\n|---|---|---|\n";
foreach ($contacts as $c) { $out .= "| {$c->id} | {$md($c->name)} | {$c->language} |\n"; }
file_put_contents("$OUT/site-map.md", $out);
$log('site-map.md: ' . count($items) . ' menu items, ' . count($arts) . ' articles');

// ---------------------------------------------------------------- inventory.md
$out = $banner('extensions, modules per position, plugins from #__extensions / #__modules / #__modules_menu');
$tplVersion = json_decode($db->setQuery("SELECT manifest_cache FROM #__extensions WHERE element = " . $db->quote($TPL) . " AND type = 'template'")->loadResult() ?: '{}', true)['version'] ?? '?';
$out .= "# Inventory — what the site is made of\n\nTemplate `$TPL` $tplVersion — snapshot $stamp.\n\n";
$out .= "## Non-core extensions (enabled)\n\n| type | element | folder | version | note |\n|---|---|---|---|---|\n";
$core = static fn ($e) => in_array($e->element, ['com_ajax', 'com_languages', 'languagecode', 'languagefilter', 'languages', 'mod_languages'], true);
$baseLike = static fn (string $el) => $BASE_TPL !== '' && ($el === $BASE_TPL || str_starts_with($el, $BASE_TPL));
foreach ($q("SELECT type, element, folder, name, manifest_cache FROM #__extensions WHERE enabled = 1 AND (element LIKE '%t4%' OR element LIKE '%ja%' OR element LIKE 'tracy%' OR element LIKE '%akeeba%' OR element LIKE '%claude%' OR (type = 'package' AND element LIKE 'pkg_%-%') OR element IN ('com_ajax','com_languages','languagecode','languagefilter','mod_languages')) ORDER BY type, folder, element") as $e) {
    $m = json_decode($e->manifest_cache ?: '{}', true) ?: [];
    $note = $core($e) ? 'Joomla core (multilingual)' : '';
    if ($e->element === $TPL) { $note = 'THE template'; }
    if ($e->element === 't4') { $note = 'T4 framework — layouts, megamenu, off-canvas, optimize cache'; }
    if ($e->element === 'mod_ja_acm') { $note = 'JA ACM — every designed block is one of these'; }
    if ($baseLike($e->element)) { $note = "$inherited — not used by the site"; }
    if ($e->element === 'com_jaextmanager' || str_contains($e->element, 'akeeba')) { $note = 'build tooling — not used by the site'; }
    if (preg_match('/^pkg_[a-z]{2,3}-[A-Z]{2}$/', $e->element)) { $on = in_array(substr($e->element, 4), array_map(static fn ($l) => $l->lang_code, $langs), true); $note = $on ? 'site language (content language published)' : 'installed, not enabled — docs/languages.md'; }
    if (str_contains($e->element, 'claudecowork')) { $note = 'the agent\'s read/write door — docs/cowork-api.md (never raw SQL)'; }
    $out .= "| {$e->type} | `{$e->element}` | {$e->folder} | " . ($m['version'] ?? '') . " | $note |\n";
}
$out .= "\n## Site modules by position (published)\n\n";
$mods = $q("SELECT m.id, m.title, m.module, m.position, m.language, m.published, m.note, m.params, m.ordering, (SELECT GROUP_CONCAT(menuid) FROM #__modules_menu mm WHERE mm.moduleid = m.id) menus FROM #__modules m WHERE m.client_id = 0 AND m.published = 1 ORDER BY m.position, m.ordering, m.language");
$byPos = [];
foreach ($mods as $m) { $byPos[$m->position][] = $m; }
$itemsById = []; foreach ($items as $it) { $itemsById[$it->id] = $it; }
$assign = static function ($m) use ($itemsById) {
    if ($m->menus === null || $m->menus === '') { return 'none'; }
    $ids = array_map('intval', explode(',', $m->menus));
    if (in_array(0, $ids, true)) { return 'all pages'; }
    if ($ids[0] < 0) { return 'all except ' . count($ids); }
    $names = array_map(static fn ($i) => isset($itemsById[$i]) ? $itemsById[$i]->title : "#$i", array_slice($ids, 0, 4));
    return implode(', ', $names) . (count($ids) > 4 ? ' +' . (count($ids) - 4) : '');
};
$acmType = static function ($m) use ($TPL) {
    if ($m->module !== 'mod_ja_acm') { return ''; }
    $p = json_decode($m->params ?: '{}', true) ?: [];
    $cfg = json_decode($p['jatools-config'] ?? '{}', true) ?: [];
    $t = (string) ($cfg[':type'] ?? '');
    return str_starts_with($t, "$TPL:") ? substr($t, strlen("$TPL:")) : $t;
};
$layoutOf = static function ($m) { $p = json_decode($m->params ?: '{}', true) ?: []; return $p['layout'] ?? ''; };
foreach ($byPos as $pos => $list) {
    $out .= "### `$pos` (" . count($list) . ")\n\n| id | title | module | ACM block / layout | lang | shown on |\n|---|---|---|---|---|---|\n";
    foreach ($list as $m) {
        $kind = $m->module === 'mod_ja_acm' ? '`' . $acmType($m) . '`' : ($layoutOf($m) ? '`' . $layoutOf($m) . '`' : '');
        $out .= "| {$m->id} | {$md($m->title)} | {$m->module} | $kind | {$m->language} | {$md($assign($m))} |\n";
    }
    $out .= "\n";
}
$out .= "## Plugins enabled (folders the site depends on)\n\n| folder | plugins |\n|---|---|\n";
foreach ($q("SELECT folder, GROUP_CONCAT(element ORDER BY element SEPARATOR ', ') els FROM #__extensions WHERE type = 'plugin' AND enabled = 1 AND folder IN ('content','system','finder','fields','editors-xtd','privacy','user') GROUP BY folder ORDER BY folder") as $p) { $out .= "| {$p->folder} | {$p->els} |\n"; }
$out .= "\n## Content languages\n\n| code | sef | title |\n|---|---|---|\n";
foreach ($langs as $l) { $out .= "| {$l->lang_code} | `/{$l->sef}/` | {$md($l->title)} |\n"; }
$fields = $q("SELECT f.id, f.title, f.name, f.type, f.context, f.language, f.params, (SELECT GROUP_CONCAT(c.title) FROM #__fields_categories fc JOIN #__categories c ON c.id = fc.category_id WHERE fc.field_id = f.id) cats FROM #__fields f WHERE f.state = 1 ORDER BY f.context, f.ordering");
$out .= "\n## Custom fields (`com_fields`) — " . count($fields) . "\n\n| id | name | type | context | lang | categories |\n|---|---|---|---|---|---|\n";
foreach ($fields as $f) { $out .= "| {$f->id} | `{$f->name}` — {$md($f->title)} | {$f->type} | {$f->context} | {$f->language} | {$md($f->cats)} |\n"; }
$ovr = [];
if (is_dir("$T/html")) {
    $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator("$T/html", FilesystemIterator::SKIP_DOTS));
    foreach ($it as $f) { if ($f->getExtension() === 'php') { $ovr[] = substr($f->getPathname(), strlen("$T/html/")); } }
}
sort($ovr);
$out .= "\n## Template overrides (`templates/$TPL/html/`) — " . count($ovr) . "\n\n";
foreach ($ovr as $o) { $out .= "- `$o`\n"; }
file_put_contents("$OUT/inventory.md", $out);
$log('inventory.md: ' . count($mods) . ' modules in ' . count($byPos) . ' positions');

// ---------------------------------------------------------------- blocks.md
$usage = [];
foreach ($mods as $m) { if ($m->module === 'mod_ja_acm') { $usage[$acmType($m)][] = $m; } }
$out = $banner('ACM block catalogue from acm/*/tmpl/*.xml + usage from #__modules');
$out .= "# Blocks — the ACM catalogue (`templates/$TPL/acm/`)\n\n";
$out .= "Every designed section is a `mod_ja_acm` module whose type is `$TPL:<block>`. Fields below are the admin form (`tmpl/<layout>.xml`); a fieldset marked *rows* repeats. Create one from Admin → Content → Site Modules → New → JA ACM → the `$TPL` block group, or through the Cowork door: `content.update` kind `module`, `module` = `mod_ja_acm`, `params` copied from an existing module of the same block via `content.get` (`cowork-api.md` §5).\n\nField types are Joomla form fields: `text` one-line input · `textarea` multi-line · `list` dropdown (options listed) · `radio` buttons · `media` image picker (path under `images/`) · `menuitem` menu-item picker · `url` link · `number`/`integer` · `checkbox`/`checkboxes` · `sql` picker fed by a query (categories, articles) · a fieldset marked *rows* is a repeating group (the admin form shows + / − per row).\n\n";
$dirs = array_filter(glob("$T/acm/*") ?: [], 'is_dir');
$listed = 0;
foreach ($dirs as $d) {
    $name = basename($d);
    $layouts = glob("$d/tmpl/*.xml");
    if (!$layouts) { continue; }
    $used = $usage[$name] ?? [];
    if (!$ours($name, $BLOCK_PREFIX) && !$used) { continue; } // leftovers of the base are listed at the end
    $listed++;
    $cfg = @simplexml_load_file("$d/config.xml");
    $out .= "## `$name` — " . $md($cfg->title ?? $name) . "\n\n";
    $positions = array_unique(array_map(static fn ($m) => $m->position, $used));
    $out .= $used ? "Used " . count($used) . "× in `" . implode('`, `', $positions) . "`.\n\n" : "**Not used by any module yet.**\n\n";
    foreach ($layouts as $lx) {
        $x = @simplexml_load_file($lx);
        if (!$x) { continue; }
        $out .= "**Layout `" . basename($lx, '.xml') . "`** — " . $md($x->title ?? '') . "\n\n| fieldset | field | type | label | default / options |\n|---|---|---|---|---|\n";
        foreach ($x->fields->fieldset ?? [] as $fs) {
            $fsName = (string) $fs['name'] . (((string) $fs['multiple']) === '1' ? ' *(rows)*' : '');
            foreach ($fs->field as $f) {
                $opts = [];
                foreach ($f->option as $o) { $opts[] = (string) $o['value']; }
                $extra = (string) ($f['default'] ?? '');
                if ($opts) { $extra = ($extra !== '' ? "$extra · " : '') . implode(' / ', $opts); }
                $out .= "| $fsName | `{$f['name']}` | {$f['type']} | {$md($f['label'])} | {$md($extra)} |\n";
            }
        }
        $out .= "\n";
    }
}
$left = [];
foreach ($dirs as $d) { $n = basename($d); if (!$ours($n, $BLOCK_PREFIX) && empty($usage[$n]) && glob("$d/tmpl/*.xml")) { $left[] = $n; } }
if ($left) { $out .= "## $inherited, unused — do not build on these\n\n`" . implode('`, `', $left) . "`\n"; }
file_put_contents("$OUT/blocks.md", $out);
$log("blocks.md: $listed blocks, " . count($left) . ' unused leftovers');

// ---------------------------------------------------------------- positions.md
$xml = simplexml_load_file("$T/templateDetails.xml");
$positions = []; foreach ($xml->positions->position ?? [] as $p) { $positions[] = (string) $p; }
$out = $banner('positions from templateDetails.xml, rows from etc/layout/*.json, page→style from #__menu' . ($purpose ? ', purposes from ' . basename($purposesFile) : ''));
$out .= "# Positions & layouts\n\n";
$out .= "## Layouts (`etc/layout/*.json`) — row order top to bottom\n\n";
$posInLayout = [];
$leftLayouts = [];
foreach (glob("$T/etc/layout/*.json") ?: [] as $lf) {
    $name = basename($lf, '.json');
    if (!$ours($name, $LAYOUT_PREFIX)) { $leftLayouts[] = $name; continue; }
    $j = json_decode(file_get_contents($lf), true);
    $out .= "### `$name`\n\n| row | class | cells (left → right) |\n|---|---|---|\n";
    foreach ($j['layout']['sections'] ?? [] as $row) {
        $cells = [];
        foreach ($row['contents'] ?? [] as $col) {
            $t = $col['type'] ?? '';
            $w = isset($col['col']) && $col['col'] !== '' ? " ({$col['col']}/12)" : '';
            if ($t === 'positions') { $ps = array_filter(array_map('trim', explode(',', (string) ($col['positions'] ?? $col['name'] ?? '')))); foreach ($ps as $p) { $posInLayout[$p][] = $name; } $cells[] = implode(' · ', array_map(static fn ($p) => "`$p`", $ps)) . $w . (!empty($col['style']) ? " chrome `{$col['style']}`" : ''); }
            elseif ($t === 'block') { $cells[] = 'block `' . ($col['name'] ?? '') . '`'; }
            elseif ($t === 'component') { $cells[] = '**component**' . $w; }
            else { $cells[] = trim($t . ' `' . ($col['name'] ?? '') . '`'); }
        }
        $out .= "| {$md($row['name'] ?? '')} | `{$md($row['extra_class'] ?? '')}` | " . implode('; ', $cells) . " |\n";
    }
    $out .= "\n";
}
if ($leftLayouts) { $out .= "$inherited, not assigned to any style — ignore: `" . implode('`, `', $leftLayouts) . "`.\n\n"; }
$out .= "## Which pages use which style / layout\n\n";
foreach ($styles as $s) {
    $p = json_decode($s->params ?: '{}', true) ?: [];
    $n = count(array_filter($items, static fn ($i) => (int) $i->template_style_id === (int) $s->id));
    $out .= "- **{$md($s->title)}** (style {$s->id}" . ($s->home ? ', default' : '') . "): layout `" . ($p['typelist-layout'] ?? '') . "`" . (!empty($p['sub-layout']) ? ", sub-layout `{$p['sub-layout']}` for pages without a menu item" : '') . " — " . ($s->home ? 'every item not listed below' : "$n menu items assign it explicitly") . "\n";
}
$out .= "\n## All " . count($positions) . " positions (`templateDetails.xml`)\n\n| position | in layout | modules now | purpose |\n|---|---|---|---|\n";
foreach ($positions as $p) {
    $n = count($byPos[$p] ?? []);
    $why = $purpose[$p] ?? (preg_match('/^([a-z]+)-page(-split|-end)?$/', $p, $mm) ? ucfirst($mm[1]) . ' page body' . ($mm[2] ?? '' ? ' (' . ltrim($mm[2], '-') . ' part, loaded by {loadposition})' : ' ({loadposition} in the article)') : '');
    $out .= "| `$p` | " . implode(', ', array_unique($posInLayout[$p] ?? [])) . " | $n | {$md($why)} |\n";
}
file_put_contents("$OUT/positions.md", $out);
$log('positions.md: ' . count($positions) . ' positions' . ($purpose ? '' : ' (no positions.purposes.json — purpose column is empty except *-page)'));
